INSERT  IGNORE INTO `tbl_custom_page` (`id`, `title`, `type`, `content`, `login`, `show_top`, `page_name`, `language`) VALUES (4,'Index Page','index','&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;col card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;text-center &quot;&gt;&lt;i class=&quot;fal fa-life-ring big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;24 Hours Support&lt;/h2&gt;\r\n&lt;p&gt;Support 24 hours / 7 days-a-week. {$companyname} operates a 24 hour/7 day-a-week email &amp;amp; remote support services that is staffed to handle any issue or question for the systems that we develop or support. Handled directly by our knowledgeable staff ensuring a quick and accurate response&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;col card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;rounded-20 text-center highlighted h-100&quot;&gt;&lt;i class=&quot;fal fa-tags big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;Attractive Prices&lt;/h2&gt;\r\n&lt;p&gt;If you find a cheaper price from our competitors but you still want to use {$companyname} services, please feel free to contact us. all our advertised prices can be negotoated and we can always beat the competition&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;col  card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;text-center &quot;&gt;&lt;i class=&quot;fal fa-info big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;Simple Instruction&lt;/h2&gt;\r\n&lt;p&gt;Our instructions are easy to follow and only require that you can enter the unlocking code using your keypad. if you can dial a telephone number, then you can enter the code!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;m-0 row&quot;&gt;\r\n&lt;div class=&quot;col card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;rounded-20 text-center highlighted h-100&quot;&gt;&lt;i class=&quot;fal fa-lock big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;Absolutely Safe&lt;/h2&gt;\r\n&lt;p&gt;Completely safe, with no risk to your phone or hardware. No software downloads are required. Alongside opening, your money are completely secure as well. &amp;nbsp; &amp;nbsp;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;col card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;text-center &quot;&gt;&lt;i class=&quot;fal fa-dollar-sign big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;Money Back Guarantee&lt;/h2&gt;\r\n&lt;p&gt;All of the services on our websites are covered by our&amp;nbsp;100% Money Back Guarantee. We provide such a guarantee to give honest customers the reassurance that the opening service&amp;nbsp;they are ordering will be delivered in good faith.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;col card mw-320  wow bounceIn&quot;&gt;\r\n&lt;div class=&quot;rounded-20 text-center highlighted h-100&quot;&gt;&lt;i class=&quot;fal fa-envelope big-icon&quot;&gt;&lt;/i&gt;\r\n&lt;h2 class=&quot;m-2&quot;&gt;Expeditious Delivery&lt;/h2&gt;\r\n&lt;p&gt;All open codes and open confirmations are sent by e-mail to the e-mail address that the customer provides on the order form. We make sure the delivery of opening codes is time-efficient.&amp;nbsp;If delayed, we\'ll&amp;nbsp;inform our clients / resellers via e-mail.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;',1,1,'','English'),(5,'terms&amp;condition','terms','<p><strong>terms and condition of using gsmbackbase</strong></p>',0,0,'terms &amp; conditions',''),(6,'Contact Us','contact','',0,0,'','');
